INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Software > Konfiguration und Inbetriebnahme > Betriebssysteme > macOS
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann macOS auf jeder beliebigen Hardware installiert werden?', 2, '[{"text": "Nein", "correct": true, "because": "macOS ist auf Apple-Hardware beschränkt"}, {"text": "Ja", "correct": false, "because": "Kompatibilität ist eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Konfiguration von macOS immer Benutzerkonten erstellt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Erforderlich für die Nutzung"}, {"text": "Nein", "correct": false, "because": "Benutzerkonto ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist macOS ohne Internetverbindung vollständig konfigurierbar?', 2, '[{"text": "Ja", "correct": true, "because": "Grundkonfiguration ist offline möglich"}, {"text": "Nein", "correct": false, "because": "Internet nicht zwingend nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Können bei der Inbetriebnahme von macOS Sicherheitsfunktionen deaktiviert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Einstellungen anpassbar"}, {"text": "Nein", "correct": false, "because": "Deaktivierung möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist macOS immer mit einer grafischen Benutzeroberfläche ausgestattet?', 2, '[{"text": "Ja", "correct": true, "because": "GUI ist Standard"}, {"text": "Nein", "correct": false, "because": "Keine reine Kommandozeile"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt ist bei der Inbetriebnahme von macOS am wichtigsten?', 3, '[{"text": "Apple-ID-Anmeldung", "correct": true, "because": "Ermöglicht Zugriff auf Dienste"}, {"text": "Farbauswahl", "correct": false, "because": "Ästhetisch, nicht funktional"}, {"text": "Hardwaretest", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug wird zur Wiederherstellung von macOS verwendet?', 2, '[{"text": "macOS-Wiederherstellung", "correct": true, "because": "Integriertes Tool"}, {"text": "Task-Manager", "correct": false, "because": "Windows-spezifisch"}, {"text": "BIOS", "correct": false, "because": "Hardwareebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion hilft bei der Netzwerkkonfiguration von macOS?', 2, '[{"text": "Systemeinstellungen", "correct": true, "because": "Zentrale Steuerung"}, {"text": "Terminal", "correct": false, "because": "Erweiterte Nutzung"}, {"text": "Finder", "correct": false, "because": "Dateiverwaltung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hardware ist für macOS zwingend erforderlich?', 3, '[{"text": "Apple-Gerät", "correct": true, "because": "macOS läuft nur auf Apple-Hardware"}, {"text": "Standard-PC", "correct": false, "because": "Nicht offiziell unterstützt"}, {"text": "Linux-Server", "correct": false, "because": "Falsches System"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil von macOS bei der Konfiguration?', 2, '[{"text": "Einfache Benutzerführung", "correct": true, "because": "Intuitive Oberfläche"}, {"text": "Kostenlosigkeit", "correct": false, "because": "Mit Hardware verbunden"}, {"text": "Minimale Anforderungen", "correct": false, "because": "Spezifische Hardware nötig"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind bei der Inbetriebnahme von macOS typisch?', 4, '[{"text": "Sprachauswahl", "correct": true, "because": "Erster Konfigurationsschritt"}, {"text": "Apple-ID-Anmeldung", "correct": true, "because": "Für Dienste nötig"}, {"text": "Netzwerkeinrichtung", "correct": true, "because": "Verbindung herstellen"}, {"text": "Hardwareformatierung", "correct": false, "because": "Nicht Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen können bei der macOS-Konfiguration angepasst werden?', 3, '[{"text": "Sicherheitseinstellungen", "correct": true, "because": "Schutz anpassbar"}, {"text": "Netzwerkeinstellungen", "correct": true, "because": "Verbindung konfigurierbar"}, {"text": "Benutzerkonten", "correct": true, "because": "Zugriff steuerbar"}, {"text": "Prozessorleistung", "correct": false, "because": "Hardwareebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet macOS bei der Inbetriebnahme?', 3, '[{"text": "Intuitive Bedienung", "correct": true, "because": "Einfache Oberfläche"}, {"text": "Integration mit Apple-Diensten", "correct": true, "because": "iCloud und mehr"}, {"text": "Automatische Updates", "correct": true, "because": "Sicherheit gewährleistet"}, {"text": "Kostenfreiheit", "correct": false, "because": "Hardwarekosten gebunden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Konfiguration von macOS auftreten?', 4, '[{"text": "Inkompatible Hardware", "correct": true, "because": "Nur Apple-Geräte"}, {"text": "Fehlende Internetverbindung", "correct": true, "because": "Für Updates nötig"}, {"text": "Komplexe Einstellungen", "correct": true, "because": "Erfordert Wissen"}, {"text": "Langsame Druckgeschwindigkeit", "correct": false, "because": "Druckerabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools unterstützen die macOS-Konfiguration?', 3, '[{"text": "Systemeinstellungen", "correct": true, "because": "Zentrale Steuerung"}, {"text": "Terminal", "correct": true, "because": "Erweiterte Befehle"}, {"text": "Time Machine", "correct": true, "because": "Backup und Wiederherstellung"}, {"text": "Multimeter", "correct": false, "because": "Hardwarewerkzeug"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) macOS läuft nur auf Apple-Hardware. b) Die Konfiguration erfordert keine Benutzerkonten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Apple ja, Konten nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Apple-ID ist für macOS-Dienste wichtig. b) macOS ist ohne Internetverbindung nicht nutzbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Apple-ID ja, offline möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Systemeinstellungen steuern die macOS-Konfiguration. b) macOS ist für Standard-PCs optimiert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Einstellungen ja, nur Apple-Hardware"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) macOS-Wiederherstellung hilft bei Problemen. b) Sicherheitsfunktionen sind nicht anpassbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wiederherstellung ja, Anpassung möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) macOS bietet eine intuitive Benutzeroberfläche. b) Die Inbetriebnahme erfordert immer einen Techniker.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Intuitiv ja, Techniker nicht nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

